let lang=localStorage.getItem('language')||'ar', products=[],settings={},cart=JSON.parse(localStorage.getItem('cart')||'[]'),category='all',adminData=null,view='inventory',orderFilter='all';
let activePhotoUpload=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),t=(ar,en)=>lang==='ar'?ar:en,price=n=>(n/1000).toFixed(3)+' '+t('ر.ع.','OMR');
const seedNames=['My Arabic Alphabet','My Little Animal World','Bedtime Stories','My First Words','Think & Play','Silicone Stacking Rings'];
const pname=p=>lang==='en'?(p.name_en||seedNames[p.id-1]||p.name):p.name;
const productRoute=location.pathname.match(/^\/products\/([1-9][0-9]*)\/?$/);
let productPhotoIndex=0;
const productPhotos=p=>Array.isArray(p.images)&&p.images.length?p.images:p.image_url?[p.image_url]:[];
const ageRanges=['0–1','1–2','2–3','3–5','5–8'];
const productAges=p=>Array.isArray(p.ages)?p.ages:ageRanges.includes(p.age)?[p.age]:[];
const ageLabel=p=>productAges(p).length?productAges(p).join(' / ')+' '+t('سنوات','years'):t('العمر غير محدد','Age not specified');
const desc=p=>lang==='en'?(p.description_en||p.description||'Description coming soon.'):p.description;
function freeDeliveryNote(total=null){return total!==null&&total>50000?t('طلبك مؤهل للتوصيل المجاني داخل سلطنة عُمان (أكثر من ٥٠ ر.ع.).','Your order qualifies for free delivery within Oman (over OMR 50).'):t('توصيل مجاني داخل سلطنة عُمان للطلبات التي تزيد عن ٥٠ ر.ع. تُؤكد رسوم التوصيل للطلبات الأخرى قبل الدفع.','Free delivery within Oman on orders over OMR 50. Delivery charges for other orders are confirmed before payment.')}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const a=await r.json();if(!r.ok){const error=Error(a.error||'Request failed');error.status=r.status;throw error}return a}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('.close').onclick=()=>{if(!activePhotoUpload)$('#modal').close()};$('#modal').onclick=e=>{if(e.target===$('#modal')&&!activePhotoUpload)$('#modal').close()};
$('#modal').addEventListener('cancel',e=>{if(activePhotoUpload)e.preventDefault()});
const languageButton=document.createElement('button');languageButton.className='plain';languageButton.id='language';$('header nav').append(languageButton);languageButton.onclick=()=>{lang=lang==='ar'?'en':'ar';localStorage.setItem('language',lang);$('#modal').close();translate();render();if(adminData)renderAdmin()};
const arOriginal=new Map();
const translations={'.floating-tag':'Made for little discoveries ♡','.announcement':'✦ Free delivery within Oman on orders over OMR 50 ✦','nav a[data-nav="collection"]':'Shop collection','nav a[data-nav="ages"]':'Shop by age','#admin-open':'Manage shop','.hero-copy .eyebrow':'LITTLE CURIOSITIES. ENDLESS POSSIBILITIES.','.hero-copy h1':'Little stories,<br><em>big worlds.</em>','.hero-copy>p':'Arabic and English books and thoughtful play.<br>For growing imaginations and everyday discoveries.','.hero-copy .button':'Explore their world <span>→</span>','.hero-note':'✧ Little moments of learning. Memories that stay.','.benefits':'<span>✧ Chosen for every little stage</span><span>◉ Arabic & English books</span><span>♡ From our family to yours</span>','.age-section .eyebrow':'EVERY STAGE HAS A STORY','.age-section h2':'Find their next little discovery','.age-options':'<button data-age="0–1">First discoveries <b>Ages 0–1 ↗</b></button><button data-age="1–2">Little steps <b>Ages 1–2 ↗</b></button><button data-age="2–3">Growing curiosity <b>Ages 2–3 ↗</b></button><button data-age="3–5">Learn & play <b>Ages 3–5 ↗</b></button><button data-age="5–8">Little adventurers <b>Ages 5–8 ↗</b></button>','#collection .eyebrow':'SMALL THINGS. MEANINGFUL DISCOVERIES.','#collection h2':'Made for moments together','.filters .tabs':'<button class="active" data-category="all">All discoveries</button><button data-category="books">Books</button><button data-category="toys">Toys</button>','.demo-note':'Prices are in OMR. Delivery charges are confirmed before payment. Products marked unavailable cannot be ordered.','.story .eyebrow':'MORE THAN A BOOK OR A TOY','.story h2':'A little space for their big dreams.','.story p':'The best learning starts with curiosity, and time spent together.','.story a':'Start your story →','footer p':'Read. Play. Grow together.','footer>span':'Sultanate of Oman · OMR'};
function translate(){document.title=t('Little Marvels | lil.Marvels | حكاية صغيرة، عالم كبير','Little Marvels | lil.Marvels | Little stories, big worlds');document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';for(const [s,en] of Object.entries(translations)){const el=$(s);if(!arOriginal.has(s))arOriginal.set(s,el.innerHTML);el.innerHTML=lang==='en'?en:arOriginal.get(s)}$('#language').textContent=lang==='ar'?'English':'العربية';$('#search').placeholder=t('ابحث عن حكاية أو لعبة…','Find a story or a toy…');$('#age-filter option').textContent=t('كل الأعمار','All ages');$('#cart-open').innerHTML=t('حقيبة التسوّق','Shopping bag')+' <b id="cart-count">0</b>';bindFilters();updateCount()}
function bindFilters(){$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.onclick=()=>{category=b.dataset.category;render();bindFilters()}});$$('[data-age]').forEach(b=>b.onclick=()=>{$('#age-filter').value=b.dataset.age;render();$('#collection').scrollIntoView()})}
$('#search').oninput=render;$('#age-filter').onchange=render;
function updateCount(){localStorage.setItem('cart',JSON.stringify(cart));$('#cart-count').textContent=cart.reduce((n,l)=>n+l.quantity,0);renderQuickCart()}
const optionsFor=p=>p?.options||[];
const displayPrice=p=>optionsFor(p).length?Math.min(...optionsFor(p).map(o=>o.price??p.price)):p.price;
function cartInfo(line){const p=products.find(p=>p.id===line.id);if(!p)return {valid:false,price:0,stock:0};const option=optionsFor(p).find(o=>o.id===line.option_id);const valid=optionsFor(p).length?Boolean(option):!line.option_id;return {p,option,valid,price:option?.price??p.price,stock:option?.stock??p.stock,label:option?.label||''}}
function cleanCart(){const old=cart.length;cart=cart.filter(line=>cartInfo(line).valid);if(old!==cart.length)toast(t('بعض المنتجات أو الخيارات تغيرت؛ أضفها مجدداً','Some products or options changed; please select them again'));updateCount()}
function renderQuickCart(){
 const bar=$('#quick-cart');if(!bar)return;
 const visible=cart.length>0&&products.length>0&&$('#admin').hidden;
 bar.hidden=!visible;document.body.classList.toggle('has-quick-cart',visible);if(!visible)return;
 const count=cart.reduce((sum,item)=>sum+item.quantity,0),total=cart.reduce((sum,item)=>sum+cartInfo(item).price*item.quantity,0);
 bar.innerHTML=`<div class="quick-cart-summary"><strong>${t('في حقيبتك: ','In your cart: ')}${count} ${t('قطعة','items')}</strong><span>${t('مجموع المنتجات','Product subtotal')}: ${price(total)}</span></div><button type="button" id="quick-view-cart">${t('عرض الحقيبة','View cart')}</button><button type="button" id="quick-checkout">${t('إتمام الطلب','Checkout')} ←</button>`;
 $('#quick-view-cart').onclick=showCart;$('#quick-checkout').onclick=checkout;
}
function render(){if(productRoute){renderProductPage();updateCount();return}const q=$('#search').value.trim().toLowerCase(),age=$('#age-filter').value;const list=products.filter(p=>(category==='all'||p.category===category)&&(age==='all'||productAges(p).includes(age))&&(p.name+' '+pname(p)+' '+p.description).toLowerCase().includes(q));$('#result-count').textContent=list.length+' '+t('اكتشافات صغيرة','little discoveries');$('#products').innerHTML=list.length?list.map(p=>`<article class="product-card"><a class="product-image" href="/products/${p.id}" data-detail="${p.id}" aria-label="${esc(pname(p))}"><span class="badge">${esc(ageLabel(p))}</span>${p.image_url?`<img class="product-photo" src="${esc(p.image_url)}" alt="${esc(pname(p))}" loading="lazy">`:`<div class="mini-book"><strong>${esc(p.emoji)}</strong><small>${esc(pname(p))}</small></div>`}</a><div class="product-meta"><span>${p.category==='books'?t('كتب للصغار','LITTLE READERS'):t('لعب واكتشاف','LITTLE EXPLORERS')}</span><span>${esc(p.language)}</span></div><h3><a href="/products/${p.id}">${esc(pname(p))}</a></h3>${p.stock?'':`<p class="stock-note">${t('غير متوفر حالياً','Currently unavailable')}</p>`}<div class="product-bottom"><strong>${optionsFor(p).length?t('من ','From '):''}${price(displayPrice(p))}</strong><button class="add" data-add="${p.id}" ${p.stock<1?'disabled':''} aria-label="${t('أضف إلى الحقيبة','Add to bag')}">${p.stock?'+':'–'}</button></div></article>`).join(''):`<p class="empty">${t('لم نجد منتجات مطابقة','No matching discoveries yet.')}</p>`;$$('[data-add]').forEach(b=>b.onclick=()=>add(+b.dataset.add));updateCount()}
function add(id,quantity=1,optionId=null){const p=products.find(p=>p.id===id);if(!p||!Number.isInteger(quantity)||quantity<1)return;if(optionsFor(p).length&&!optionId){detail(id);return}const option=optionsFor(p).find(o=>o.id===optionId);if(optionId&&!option)return;const line=cart.find(l=>l.id===id&&(l.option_id||null)===(optionId||null));if((line?.quantity||0)+quantity>Math.min(option?.stock??p.stock,100))return toast(t('الكمية المطلوبة تتجاوز المخزون المتوفر','The requested quantity exceeds available stock'));if(line)line.quantity+=quantity;else cart.push({id,quantity,...(optionId?{option_id:optionId}:{})});updateCount();toast(t('أُضيف إلى الحقيبة ♡','Added to your bag ♡'))}
function detail(id){location.href='/products/'+id}
function renderProductPage(){
 $('#shop').hidden=true;const area=$('#product-page');area.hidden=!$('#admin').hidden;
 $('nav a[data-nav="collection"]').href='/#collection';$('nav a[data-nav="ages"]').href='/#ages';
 const p=products.find(p=>p.id===+productRoute[1]);
 if(!p){area.innerHTML=`<h1>${t('المنتج غير متوفر','Product unavailable')}</h1><a class="button" href="/">${t('العودة للمتجر','Back to shop')}</a>`;return}
 const photos=productPhotos(p);productPhotoIndex=Math.min(productPhotoIndex,Math.max(0,photos.length-1));
 document.title=pname(p)+' | Little Marvels';
 area.innerHTML=`<a class="product-back" href="/#collection">${t('← العودة إلى المجموعة','← Back to collection')}</a><section class="product-layout"><div class="product-gallery"><div class="gallery-stage">${photos.length?`<img id="gallery-main" src="${esc(photos[productPhotoIndex])}" alt="${esc(pname(p))}" fetchpriority="high">`:`<span class="gallery-placeholder">${esc(p.emoji||'📚')}</span>`}</div><div class="gallery-nav"><button id="photo-prev" ${photos.length<2?'disabled':''} aria-label="${t('الصورة السابقة','Previous photo')}">←</button><span id="photo-position">${photos.length?productPhotoIndex+1:0} / ${photos.length}</span><button id="photo-next" ${photos.length<2?'disabled':''} aria-label="${t('الصورة التالية','Next photo')}">→</button></div><div class="gallery-thumbs">${photos.map((url,index)=>`<button type="button" data-photo="${index}" aria-label="${t('عرض الصورة','Show photo')} ${index+1}" aria-pressed="${index===productPhotoIndex}"><img src="${esc(url)}" alt="${esc(pname(p))} · ${index+1}" loading="lazy"></button>`).join('')}</div></div><div class="product-information"><span class="eyebrow">LITTLE MARVELS</span><h1>${esc(pname(p))}</h1><div class="product-chips"><span>${esc(ageLabel(p))}</span><span>${p.language==='English'?t('الإنجليزية','English'):t('العربية','Arabic')}</span></div><strong id="detail-price" class="product-page-price">${optionsFor(p).length?t('من ','From '):''}${price(displayPrice(p))}</strong><p id="detail-stock">${p.stock>0?t('متوفر: ','In stock: ')+p.stock:t('غير متوفر حالياً','Currently unavailable')}</p>${optionsFor(p).length?`<label class="customer-option-label">${t('اختر الخيار','Choose an option')}<select id="product-option" required><option value="">${t('اختر قبل الإضافة إلى الحقيبة','Choose before adding to cart')}</option>${optionsFor(p).map(o=>`<option value="${esc(o.id)}" ${o.stock?'':'disabled'}>${esc(o.label)} · ${price(o.price??p.price)}${o.stock?'':' · '+t('غير متوفر','Unavailable')}</option>`).join('')}</select></label>`:''}<div class="product-buy"><label>${t('الكمية','Quantity')}<input id="detail-quantity" type="number" min="1" max="${p.stock}" step="1" value="1" ${p.stock?'':'disabled'}></label><button id="product-add" class="button" ${p.stock?'':'disabled'}>${t('أضف إلى الحقيبة','Add to bag')}</button></div><p class="notice">${t('التوصيل عبر جيناكم — للمنزل أو مكتب التوصيل. يُؤكد المبلغ النهائي عبر واتساب قبل التحويل.','Delivery through Geenakum · جيناكم, to your home or a delivery office. The final amount is confirmed on WhatsApp before transferring.')}</p><p class="notice delivery-promo">${freeDeliveryNote()}</p><h2>${t('وصف المنتج','Product description')}</h2><div class="full-description">${esc(desc(p))}</div></div></section>`;
 const showPhoto=index=>{if(!photos.length)return;productPhotoIndex=(index+photos.length)%photos.length;$('#gallery-main').src=photos[productPhotoIndex];$('#photo-position').textContent=(productPhotoIndex+1)+' / '+photos.length;$$('[data-photo]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.photo===productPhotoIndex)))};
 const optionSelect=$('#product-option');if(optionSelect){const choose=()=>{const option=optionsFor(p).find(o=>o.id===optionSelect.value);$('#product-add').disabled=!option||!option.stock;$('#detail-quantity').disabled=!option||!option.stock;$('#detail-quantity').max=Math.min(option?.stock||0,100);$('#detail-quantity').value=1;$('#detail-price').textContent=price(option?.price??displayPrice(p));$('#detail-stock').textContent=option?t('متوفر: ','In stock: ')+option.stock:t('اختر الخيار لمعرفة المخزون','Choose an option to see its stock')};optionSelect.onchange=choose;choose()}
 $('#photo-prev').onclick=()=>showPhoto(productPhotoIndex-1);$('#photo-next').onclick=()=>showPhoto(productPhotoIndex+1);$$('[data-photo]').forEach(b=>b.onclick=()=>showPhoto(+b.dataset.photo));
 $('#product-add').onclick=()=>{const q=$('#detail-quantity');if(!q.checkValidity()){q.reportValidity();return}const option=$('#product-option');if(option&&!option.value){option.reportValidity();return}add(p.id,Number(q.value),option?.value||null)};
}

$('#cart-open').onclick=showCart;
function showCart(){cleanCart();let total=0;modal(`<h2>${t('حقيبة الاكتشافات','Your discovery bag')}</h2>${cart.map((line,index)=>{const item=cartInfo(line);total+=line.quantity*item.price;return `<div class="cart-line"><div>${esc(pname(item.p))}${item.label?`<small class="cart-option-label">${esc(item.label)}</small>`:''}<small> · ${price(item.price)}</small></div><input aria-label="${t('الكمية','Quantity')}" type="number" min="1" max="${Math.min(item.stock,100)}" step="1" value="${line.quantity}" data-qty="${index}"><button data-remove="${index}">×</button></div>`}).join('')||`<p>${t('الحقيبة فارغة بعد','Your bag is waiting for a discovery.')}</p>`}${cart.length?`<h3>${t('المجموع','Total')}: ${price(total)}</h3><p class="notice">${freeDeliveryNote(total)}</p><button id="checkout">${t('متابعة الطلب','Continue to order')}</button>`:''}`);$$('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);showCart()});$$('[data-qty]').forEach(input=>input.onchange=()=>{const line=cart[+input.dataset.qty],item=cartInfo(line);line.quantity=Math.min(item.stock,100,Math.max(1,parseInt(input.value)||1));if(!line.quantity)cart.splice(+input.dataset.qty,1);showCart()});if($('#checkout'))$('#checkout').onclick=checkout}

function bankInfo(){
const row=(label,value)=>value?`<div class="payment-row"><span>${label}</span><div><bdi>${esc(value)}</bdi><button type="button" class="copy-payment" data-copy="${esc(value)}">${t('نسخ','Copy')}</button></div></div>`:'';
return `<div class="payment-options">${settings.transfer_phone?`<section class="phone-transfer"><span class="eyebrow">${t('الخيار الأول · سهل وسريع','FIRST OPTION · QUICK & EASY')}</span><h3>${t('التحويل برقم الهاتف','Transfer by phone number')}</h3><p>${t('اختر التحويل برقم الهاتف من تطبيق البنك، ثم أدخل الرقم التالي.','Choose transfer by phone number in your banking app, then enter this number.')}</p>${row(t('رقم الهاتف','Phone number'),settings.transfer_phone)}<p class="payment-recipient">${t('المستفيد','Recipient')}: <bdi>${esc(settings.bank_holder||'')}</bdi></p></section>`:''}${settings.bank_account||settings.bank_iban?`<details class="bank-transfer" ${settings.transfer_phone?'':'open'}><summary>${t('أو التحويل إلى الحساب البنكي','Or transfer to the bank account')}</summary><h3>${esc(settings.bank_name||'')}</h3>${row(t('اسم صاحب الحساب','Account holder'),settings.bank_holder)}${row(t('رقم الحساب','Account number'),settings.bank_account)}${row('IBAN',settings.bank_iban)}${row(t('رمز SWIFT','SWIFT code'),settings.bank_swift)}</details>`:''}<p class="payment-help">${t('تأكد من اسم المستفيد داخل تطبيق البنك قبل تأكيد التحويل.','Check the recipient name in your banking app before confirming the transfer.')}</p></div>`;
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.copy);toast(t('تم النسخ','Copied'))}catch{toast(t('يمكنك تحديد الرقم ونسخه يدوياً','Select the number to copy it manually'))}});

function whatsappOrderMessage(order,customer){
 const lines=['*Little Marvels · lil.Marvels*','*'+t('طلب','Order')+' #'+order.id+'*',t('الاسم','Name')+': '+(order.customer||customer)];
 if(order.phone)lines.push(t('رقم الهاتف','Phone')+': '+order.phone);
 lines.push('','*'+t('المنتجات المطلوبة — قائمة تجهيز الطلب','Ordered products — packing list')+'*');
 for(const [index,item] of (order.lines||[]).entries()){
  const name=(lang==='en'&&item.name_en&&item.name_en!==item.name?item.name_en+' / '+item.name:item.name)+(item.option_label?' — '+item.option_label:'');
  lines.push((index+1)+'. '+name+(item.product_id?' [#'+item.product_id+']':''),
   '   '+t('الكمية','Quantity')+': '+item.quantity+' | '+t('سعر الوحدة','Unit price')+': '+price(item.price)+' | '+t('الإجمالي','Line total')+': '+price(item.price*item.quantity));
 }
 lines.push('',t('إجمالي عدد القطع','Total units')+': '+(order.lines||[]).reduce((sum,item)=>sum+item.quantity,0),
  '*'+t('مجموع المنتجات (قبل التوصيل والضرائب)','Product subtotal (before delivery and taxes)')+': '+price(order.total)+'*','',
  '*'+t('التوصيل عبر جيناكم','Delivery through Geenakum · جيناكم')+'*',
  order.delivery_method==='office'?t('أرغب بالاستلام من مكتب التوصيل.','I would like delivery-office pickup.'):order.delivery_method==='home'?t('أرغب بالتوصيل إلى المنزل.','I would like home delivery.'):t('لم تُحدد طريقة التوصيل بعد.','Delivery preference not specified.'),
  t('العنوان / المكتب المفضل','Address / preferred office')+': '+(order.address||'—'),'','*'+t('بيانات الدفع','Payment details')+'*');
 if(settings.transfer_phone)lines.push(t('التحويل برقم الهاتف — الخيار الأول','Transfer by phone number — first option')+': '+settings.transfer_phone);
 for(const [key,label] of [['bank_name',t('البنك','Bank')],['bank_holder',t('المستفيد','Account holder')],['bank_account',t('رقم الحساب','Account number')],['bank_iban','IBAN'],['bank_swift','SWIFT']])if(settings[key])lines.push(label+': '+settings[key]);
 lines.push('',freeDeliveryNote(order.total),'',t('يرجى تأكيد المبلغ النهائي والتوصيل لتجهيز الطلب. سأحوّل المبلغ وأرسل إثبات التحويل هنا في واتساب. الطلب غير مدفوع حتى التحقق من استلام المبلغ.','Please confirm delivery and the final amount so my order can be prepared. I will transfer and share evidence of payment here in WhatsApp. This order remains unpaid until receipt is verified.'));
 return lines.join('\n');
}
function whatsappPaymentUrl(order,customer){
 const number=String(settings.whatsapp_number||'').replace(/[^0-9]/g,'');
 return /^[1-9][0-9]{7,14}$/.test(number)?'https://wa.me/'+number+'?text='+encodeURIComponent(whatsappOrderMessage(order,customer)):'';
}

function checkout(){
 cleanCart();if(!cart.length){showCart();return}
 if(!settings.transfer_phone&&!settings.bank_account&&!settings.bank_iban)return modal(`<h2>${t('الطلبات قريباً','Orders opening soon')}</h2><p>${t('يحتاج المتجر إلى إضافة بيانات التحويل قبل استقبال الطلبات.','The shop needs to configure transfer details before accepting orders.')}</p>`);
 modal(`<h2>${t('إتمام طلبك','Place your order')}</h2><p class="notice delivery-promo">${freeDeliveryNote(cart.reduce((sum,item)=>sum+cartInfo(item).price*item.quantity,0))}</p><p class="notice">${t('سجّل طلبك ثم تابع الدفع عبر واتساب. ستفتح محادثة برسالة جاهزة تشمل رقم الطلب وبيانات التحويل؛ اضغط إرسال لمشاركتها مع المتجر، وانتظر تأكيد المبلغ النهائي قبل التحويل.','Place your order, then continue payment on WhatsApp. A prepared message includes your order number and transfer details; tap Send to share it with the shop, and wait for the final amount before transferring.')}</p><form id="checkout-form"><label>${t('الاسم','Full name')}<input name="customer" required maxlength="150" autocomplete="name"></label><label>${t('رقم الهاتف','Phone number')}<input name="phone" type="tel" required maxlength="30" autocomplete="tel"></label><p class="notice">${t('نوصل طلباتكم عبر جيناكم (Geenakum). اختر التوصيل للمنزل أو الاستلام من مكتب التوصيل. يتم تأكيد رسوم التوصيل والمبلغ النهائي عبر واتساب قبل التحويل.','We deliver through Geenakum · جيناكم. Choose home delivery or delivery-office pickup. Delivery charges and the final amount will be confirmed on WhatsApp before you transfer.')}</p><label>${t('طريقة التوصيل','Delivery preference')}<select name="delivery_method" required><option value="">${t('اختر طريقة التوصيل','Choose delivery preference')}</option><option value="home">${t('توصيل إلى المنزل','Home delivery')}</option><option value="office">${t('استلام من مكتب التوصيل','Delivery-office pickup')}</option></select></label><label><span id="delivery-address-label">${t('العنوان أو الولاية ومكتب التوصيل المفضل','Address or city and preferred delivery office')}</span><textarea name="address" required maxlength="1000" autocomplete="street-address"></textarea></label><button type="submit">${t('تسجيل الطلب والمتابعة للدفع','Place order & continue to payment')}</button></form>`);
 $('#checkout-form [name=delivery_method]').onchange=e=>{$('#delivery-address-label').textContent=e.target.value==='office'?t('الولاية ومكتب جيناكم المفضل للاستلام','City and preferred Geenakum pickup office'):t('عنوان المنزل (الولاية، المنطقة، ورقم المنزل)','Home address (city, area and house number)')};
 $('#checkout-form').onsubmit=async e=>{
 e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;
 try{
 const customer=Object.fromEntries(new FormData(e.target));
 const o=await api('/api/orders',{...customer,items:cart});
 cart=[];updateCount();
 const url=whatsappPaymentUrl(o,customer.customer);const message=whatsappOrderMessage(o,customer.customer);
 modal(`<h2>${t('تم تسجيل طلبك','Order recorded')} #${o.id}</h2><p>${t('لم يتم استلام أي دفعة. يمكنك الآن متابعة الدفع مع المتجر.','No payment has been taken. You can now arrange payment with the shop.')}</p><p>${t('مجموع المنتجات','Product subtotal')}: ${price(o.total)}</p><p class="notice delivery-promo">${freeDeliveryNote(o.total)}</p>${url?`<a id="whatsapp-pay" class="button" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${t('متابعة الدفع عبر واتساب','Continue payment on WhatsApp')} ↗</a><button id="copy-order-message" type="button">${t('نسخ رسالة الطلب كاملة','Copy full order message')}</button><p class="payment-help">${t('يفتح واتساب برسالة جاهزة تتضمن بيانات التحويل. اضغط إرسال، ثم أكمل مع المتجر وأرسل إيصال التحويل. إذا لم يفتح التطبيق، استخدم واتساب ويب.','Opens WhatsApp with a prepared message containing transfer details. Tap Send, then continue with the shop and share your transfer receipt. WhatsApp Web also works.')}</p>`:`<p class="notice">${t('لم يُضبط رقم واتساب المتجر بعد. تواصل عبر حساب إنستغرام لتأكيد طلبك.','The shop WhatsApp number is not configured yet. Contact the shop through Instagram to confirm your order.')} <a href="https://www.instagram.com/lil.marvels.om/" target="_blank" rel="noopener noreferrer" dir="ltr">@lil.marvels.om ↗</a></p>`}<p class="notice">${t('انتظر تأكيد المبلغ النهائي قبل التحويل. الطلب غير مدفوع حتى يتحقق المتجر من الاستلام.','Wait for the final amount before transferring. Your order remains unpaid until the shop verifies receipt.')}</p><details><summary>${t('عرض بيانات التحويل هنا','View transfer details here')}</summary>${bankInfo()}</details>`);
 if($('#copy-order-message'))$('#copy-order-message').onclick=async()=>{try{await navigator.clipboard.writeText(message);toast(t('تم نسخ الطلب كاملاً — الصقه في محادثة واتساب','Full order copied — paste it into the WhatsApp chat'))}catch{modal(`<h2>${t('رسالة الطلب كاملة','Full order message')}</h2><textarea class="full-order-message" readonly>${esc(message)}</textarea>`);$('.full-order-message').select()}};
 if($('#whatsapp-pay'))$('#whatsapp-pay').onclick=()=>{fetch('/api/orders/whatsapp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:o.id,token:o.payment_token}),keepalive:true}).catch(()=>{});};
 loadProducts().catch(()=>toast(t('تعذّر تحديث المخزون المعروض؛ طلبك محفوظ.','Could not refresh displayed stock; your order is saved.')));
 }catch(err){toast(err.message);b.disabled=false}
 };
}

$('#admin-open').onclick=async()=>{try{await loadAdmin();openAdmin()}catch{login()}};
function login(){
 modal(`<h2>${t('تسجيل دخول الإدارة','Shop management')}</h2><form id="login-form"><label>${t('كلمة المرور','Password')}<input name="password" type="password" required autocomplete="current-password" aria-describedby="login-error"></label><p id="login-error" class="login-error" role="alert" hidden></p><button type="submit">${t('دخول','Sign in')}</button></form><button type="button" id="forgot-password" class="recovery-link">${t('نسيت كلمة المرور؟','Forgot password?')}</button>`);
 const form=$('#login-form'),password=form.elements.password,errorNote=$('#login-error'),button=form.querySelector('button[type=submit]'),forgot=$('#forgot-password');
 forgot.onclick=passwordRecovery;
 password.oninput=()=>{errorNote.hidden=true;errorNote.textContent='';password.removeAttribute('aria-invalid')};
 form.onsubmit=async e=>{
  e.preventDefault();button.disabled=true;forgot.disabled=true;errorNote.hidden=true;password.removeAttribute('aria-invalid');let authenticated=false;
  try{await api('/api/login',Object.fromEntries(new FormData(form)));authenticated=true;await loadAdmin();$('#modal').close();openAdmin()}
  catch(error){
   const wrongPassword=!authenticated&&error.status===401;
   errorNote.textContent=wrongPassword?t('كلمة المرور غير صحيحة. حاول مرة أخرى.','Password is incorrect. Please try again.'):error.status===429?t('محاولات كثيرة. انتظر خمس دقائق ثم حاول مجدداً.','Too many attempts. Please wait five minutes and try again.'):authenticated?t('تم تسجيل الدخول، لكن تعذّر تحميل الإدارة. حاول مجدداً.','Signed in, but management could not load. Please try again.'):t('تعذّر تسجيل الدخول. تحقق من الاتصال وحاول مجدداً.','Unable to sign in. Check your connection and try again.');
   errorNote.hidden=false;if(wrongPassword){password.setAttribute('aria-invalid','true');password.focus();password.select()}
  }finally{button.disabled=false;forgot.disabled=false}
 };
}

function passwordRecovery(){
 modal(`<h2>${t('استعادة دخول الإدارة','Recover admin access')}</h2><p>${t('لمالك المتجر: يمكنك تعيين كلمة مرور جديدة من حساب الاستضافة الخاص بك. لم تُفعّل خدمة إرسال روابط الاستعادة بالبريد الإلكتروني بعد.','For the store owner: set a new password through your hosting account. Email reset links have not been configured yet.')}</p><div class="recovery-contacts"><strong>${t('بريد التواصل لاستعادة الدخول','Recovery contact emails')}</strong><a href="mailto:ahmedalraqmi1993@gmail.com" dir="ltr">ahmedalraqmi1993@gmail.com</a><a href="mailto:ahmedalraqmi93@gmail.com" dir="ltr">ahmedalraqmi93@gmail.com</a><small>${t('هذه روابط للتواصل، ولا ترسل رسائل استعادة تلقائية.','These are contact links; they do not send automated password-reset emails.')}</small></div><ol class="recovery-steps"><li>${t('افتح لوحة Render وسجّل الدخول بحسابك.','Open the Render dashboard and sign in to your account.')}</li><li>${t('اختر خدمة lil-marvels ثم Environment.','Select the lil-marvels service, then Environment.')}</li><li>${t('عدّل ADMIN_PASSWORD وأدخل كلمة مرور جديدة قوية.','Edit ADMIN_PASSWORD and enter a strong new password.')}</li><li>${t('احفظ التغييرات وانتظر إعادة تشغيل الخدمة وظهور الحالة Live.','Save your changes and wait for the service to restart and show Live.')}</li><li>${t('ارجع إلى المتجر وسجّل الدخول بكلمة المرور الجديدة.','Return to the shop and sign in with your new password.')}</li></ol><p class="notice">${t('لا تشارك كلمة المرور في واتساب أو في المحادثات. تغييرها لا يحذف المنتجات أو الطلبات.','Keep your password private. Changing it does not delete products or orders.')}</p><a class="button" href="https://dashboard.render.com/" target="_blank" rel="noopener noreferrer">${t('فتح لوحة Render','Open Render dashboard')} ↗</a><button type="button" id="back-to-login" class="recovery-link">${t('العودة لتسجيل الدخول','Back to sign in')}</button>`);
 $('#back-to-login').onclick=login;
}
async function loadAdmin(){adminData=await api('/api/admin')}
function openAdmin(){$('#shop').hidden=true;$('#product-page').hidden=true;$('#admin').hidden=false;renderQuickCart();renderAdmin();scrollTo(0,0)}
$('#logout').onclick=async()=>{await api('/api/logout',{});adminData=null;statsPeriod='all';statsDate=omanToday();statsRequest++;$('#shop').hidden=Boolean(productRoute);$('#product-page').hidden=!productRoute;$('#admin').hidden=true;if(productRoute)renderProductPage();renderQuickCart()};
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;renderAdmin()});
const bankTab=document.createElement('button');bankTab.dataset.view='settings';$('.admin-tabs').append(bankTab);bankTab.onclick=()=>{view='settings';renderAdmin()};
const statuses=()=>({new:t('غير مدفوع','Unpaid'),confirmed:t('تم التأكيد · غير مدفوع','Confirmed · unpaid'),paid:t('تم التحقق من التحويل','Transfer verified'),completed:t('تم الدفع والمعالجة','Paid & processed'),cancelled:t('ملغي','Cancelled')});
let statsPeriod='all',statsRequest=0;
const omanToday=()=>{const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Muscat',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-')};
let statsDate=omanToday();
async function renderStatistics(){
 const ticket=++statsRequest;
 const periods=[['all',t('تراكمي — كل الفترات','Cumulative — all time')],['day',t('يومي','Daily')],['week',t('أسبوعي','Weekly')],['month',t('شهري','Monthly')],['year',t('سنوي','Yearly')]];
 const inputType=statsPeriod==='month'?'month':statsPeriod==='year'?'number':'date';
 const value=statsPeriod==='month'?statsDate.slice(0,7):statsPeriod==='year'?statsDate.slice(0,4):statsDate;
 $('#stats-controls').innerHTML=`<div class="stats-heading"><h2>${t('إحصائيات المبيعات والتكاليف','Sales & cost statistics')}</h2><span>${t('توقيت سلطنة عُمان · الأسبوع من الأحد إلى السبت','Oman time · weeks run Sunday–Saturday')}</span></div><div class="stats-filters"><label>${t('الفترة','Period')}<select id="stats-period">${periods.map(([key,label])=>`<option value="${key}" ${key===statsPeriod?'selected':''}>${label}</option>`).join('')}</select></label>${statsPeriod==='all'?'':`<label>${statsPeriod==='week'?t('اختر أي يوم في الأسبوع المطلوب','Choose any day in the desired week'):t('التاريخ','Date')}<input id="stats-date" type="${inputType}" value="${esc(value)}" ${inputType==='number'?'min="1900" max="9998" step="1"':''}></label>`}<button id="stats-refresh">${t('تحديث الإحصائيات','Refresh statistics')}</button></div>`;
 $('#stats-period').onchange=e=>{statsPeriod=e.target.value;renderStatistics()};
 if($('#stats-date'))$('#stats-date').onchange=e=>{if(!e.target.value||!e.target.validity.valid)return;statsDate=statsPeriod==='month'?e.target.value+'-01':statsPeriod==='year'?e.target.value+'-01-01':e.target.value;renderStatistics()};
 $('#stats-refresh').onclick=renderStatistics;
 $('#metrics').setAttribute('aria-busy','true');$('#metrics').innerHTML=`<p>${t('جارٍ تحميل الإحصائيات…','Loading statistics…')}</p>`;
 try{
 const data=await api('/api/admin/stats?'+new URLSearchParams({period:statsPeriod,...(statsPeriod==='all'?{}:{date:value})}));
 if(ticket!==statsRequest||!adminData)return;
 const cards=[['sales',t('مبيعات مكتملة','Completed sales'),price(data.sales)],['product_cost',t('تكلفة المنتجات المباعة (المعروفة)','Cost of sold products (known)'),price(data.product_cost)],['gross_profit',t('الربح الإجمالي (بتكلفة معروفة)','Gross profit (known costs)'),price(data.gross_profit)],['additional_costs',t('مصاريف إضافية مسجلة','Recorded additional costs'),price(data.additional_costs)],['additional_income',t('دخل إضافي / توصيل محصل','Extra income / delivery collected'),price(data.additional_income)],['net_profit',t('صافي الربح (بالتكاليف المسجلة)','Net profit (recorded costs)'),price(data.net_profit)],['completed_orders',t('عدد الطلبات المكتملة','Completed orders'),data.completed_orders],['supplier_purchases',t('مشتريات الموردين المستلمة','Received supplier purchases'),price(data.supplier_purchases)],['unknown_cost_orders',t('طلبات بتكلفة غير معروفة','Orders with unknown cost'),data.unknown_cost_orders]];
 $('#metrics').innerHTML=cards.map(([key,label,amount])=>`<div data-stat="${key}">${label}<strong>${amount}</strong></div>`).join('');
 if(view==='expenses')drawExpenses(data);if(view==='analysis')loadSalesInsights(ticket);
 $('#stats-note').textContent=(data.period==='all'?t('إجمالي تراكمي لكل الفترات. ','Cumulative totals across all dates. '):data.start_date+' → '+data.end_date+' · ')+t('تُحسب المبيعات بتاريخ إكمال الطلب، والمشتريات بتاريخ الاستلام. صافي الربح = الربح الإجمالي + الدخل الإضافي − المصاريف المسجلة. تُحسب المصاريف والدخل الإضافي بتاريخ السجل. تُعرض مشتريات الموردين منفصلة ولا تُخصم مرتين.','Sales use the order completion date; purchases use the receipt date. Net profit = gross profit + recorded extra income − recorded expenses. Expenses and extra income use their entry dates. Supplier purchases are shown separately and not subtracted twice.')+(data.legacy_order_dates||data.legacy_purchase_dates?t(' تستخدم السجلات القديمة بلا تاريخ إكمال أو استلام تاريخ الإنشاء.',' Older records without completion or receipt dates use their creation dates.'):'');
 }catch(e){if(ticket===statsRequest){$('#metrics').innerHTML=`<p class="notice">${esc(e.message)}</p>`;$('#stats-note').textContent=''}}
 finally{if(ticket===statsRequest)$('#metrics').removeAttribute('aria-busy')}
}
let seasonYear='all',seasonProduct='all',insightsRequest=0,insightsData=null;
const monthName=(number,short=false)=>new Intl.DateTimeFormat(lang==='ar'?'ar-OM':'en-GB',{month:short?'short':'long',timeZone:'UTC'}).format(new Date(Date.UTC(2000,number-1,1)));
function insightName(row){const p=adminData.products.find(p=>p.id===row.product_id);return p?pname(p):row.name}
async function loadSalesInsights(ticket=statsRequest){
 if(view!=='analysis'||!$('#sales-insights'))return;const request=++insightsRequest;$('#sales-insights').innerHTML=`<p>${t('جارٍ تحليل المبيعات…','Loading sales analysis…')}</p>`;
 const date=statsPeriod==='month'?statsDate.slice(0,7):statsPeriod==='year'?statsDate.slice(0,4):statsDate;
 try{const data=await api('/api/admin/insights?'+new URLSearchParams({period:statsPeriod,year:seasonYear,...(statsPeriod==='all'?{}:{date})}));if(request!==insightsRequest||ticket!==statsRequest||view!=='analysis'||!adminData)return;insightsData=data;drawSalesInsights()}
 catch(error){if(request===insightsRequest&&view==='analysis')$('#sales-insights').innerHTML=`<p class="notice">${esc(error.message)}</p>`}
}
function drawSalesInsights(){
 if(!insightsData||view!=='analysis')return;const data=insightsData,products=data.seasonal_products;
 if(seasonProduct!=='all'&&!products.some(p=>String(p.product_id)===seasonProduct))seasonProduct='all';
 const selected=products.find(p=>String(p.product_id)===seasonProduct),months=selected?selected.months:data.monthly_totals,total=months.reduce((a,b)=>a+b,0),peak=Math.max(...months),peaks=months.map((n,i)=>n===peak&&n>0?i+1:null).filter(Boolean);
 const years=[...new Set([...data.years_available,...(seasonYear==='all'?[]:[seasonYear])])].sort((a,b)=>b-a);
 const peakText=total?t('أعلى الأشهر في السجلات: ','Peak recorded month(s): ')+peaks.map(n=>monthName(n)).join('، ')+' · '+peak+' '+t('قطعة في كل شهر ذروة','units in each peak month')+' ('+(100*peak/total).toFixed(1)+'% '+t('من الإجمالي لكل شهر','of total per month')+')':t('لا توجد مبيعات مكتملة لتحليلها بعد.','No completed sales to analyse yet.');
 $('#sales-insights').innerHTML=`<h2>${t('الأكثر مبيعاً','Best sellers')}</h2><p class="inventory-note">${t('حسب عدد القطع المباعة في الفترة المحددة أعلاه. تُجمع خيارات المنتج معاً، ولا تُحتسب الطلبات الملغية أو غير المكتملة.','Ranked by units sold in the period selected above. Product options are combined; cancelled and incomplete orders are excluded.')}</p>${data.bestsellers.length?`<div class="table-wrap"><table id="bestsellers-table"><thead><tr>${['#',t('المنتج','Product'),t('القطع المباعة','Units sold'),t('المبيعات','Sales'),t('عدد الطلبات','Orders')].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${data.bestsellers.map((row,index)=>{const product=adminData.products.find(p=>p.id===row.product_id);return `<tr><td>${index+1}</td><td><div class="inventory-product">${product?.image_url?`<img class="inventory-thumb" src="${esc(product.image_url)}" alt="${esc(insightName(row))}" loading="lazy">`:''}<div>${esc(insightName(row))}${product&&!product.active?`<small>${t('منتج مخفي','Hidden item')}</small>`:''}</div></div></td><td>${row.units}</td><td>${price(row.revenue)}</td><td>${row.orders}</td></tr>`}).join('')}</tbody></table></div>`:`<p class="empty">${t('لا توجد مبيعات مكتملة في هذه الفترة','No completed sales in this period.')}</p>`}<h2>${t('الأنماط الشهرية والموسمية','Monthly & seasonal patterns')}</h2><p class="notice">${t('هذه أنماط من المبيعات المسجلة، وليست توقعات. لا تكفي المبيعات القليلة أو تاريخ شهر واحد لإثبات موسمية الطلب. الأشهر بلا مبيعات مسجلة تظهر صفراً، وقد يكون السبب نفاد المخزون.','These are observed sales patterns, not forecasts. A few sales or one month of history cannot establish seasonality. Months without recorded sales show zero, which may also reflect unavailable stock.')}</p><div class="season-filters"><label>${t('سنة التحليل (مستقلة عن فلتر المبيعات)','History year (separate from sales filter)')}<select id="season-year"><option value="all">${t('كل السنوات المسجلة','All recorded years')}</option>${years.map(year=>`<option value="${year}" ${seasonYear===year?'selected':''}>${year}</option>`).join('')}</select></label><label>${t('المنتج','Product')}<select id="season-product"><option value="all">${t('جميع المنتجات','All products')}</option>${[...products].sort((a,b)=>insightName(a).localeCompare(insightName(b),lang==='ar'?'ar':'en')).map(p=>`<option value="${p.product_id}" ${seasonProduct===String(p.product_id)?'selected':''}>${esc(insightName(p))}</option>`).join('')}</select></label></div><p id="season-peak">${esc(peakText)}</p>${selected?`<p>${selected.units} ${t('قطعة مسجلة عبر','recorded units across')} ${selected.observed_month_count} ${t('أشهر فعلية','observed calendar months')} · ${selected.years.length} ${t('سنوات','years')}${selected.limited_history?' · '+t('تاريخ محدود — لا يؤكد موسمية متكررة','Limited history — recurring seasonality not established'):''}</p>`:''}<div class="month-chart-scroll"><div class="month-chart" role="img" aria-label="${esc(t('القطع المباعة حسب الشهر: ','Units sold by month: ')+months.map((n,i)=>monthName(i+1)+' '+n).join('، '))}">${months.map((n,i)=>`<div class="month-column" title="${esc(monthName(i+1))}: ${n}"><span>${n}</span><div class="month-bar ${n===peak&&n>0?'month-peak':''}" style="height:${peak?Math.max(3,Math.round(120*n/peak)):3}px"></div><small>${esc(monthName(i+1,true))}</small></div>`).join('')}</div></div><p class="inventory-note">${t('القياس بعدد القطع، بتوقيت عُمان. تُستخدم تواريخ إكمال الطلبات، وتاريخ الإنشاء للسجلات القديمة بلا تاريخ إكمال.','Measured in units, using Oman time. Completion dates are used; older records without a completion date use their creation date.')}</p>${products.length?`<div class="table-wrap"><table id="seasonal-table"><thead><tr>${[t('المنتج','Product'),t('ذروة المبيعات المسجلة','Recorded peak month(s)'),t('نسبة كل شهر ذروة','Share per peak month'),t('إجمالي القطع','Total units'),''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${products.slice(0,10).map(p=>`<tr><td>${esc(insightName(p))}${p.limited_history?`<small>${t('تاريخ محدود','Limited history')}</small>`:''}</td><td>${p.peak_months.map(n=>monthName(n)).join('، ')}</td><td>${p.peak_share}%</td><td>${p.units}</td><td><button data-explore-season="${p.product_id}">${t('عرض الأشهر','View months')}</button></td></tr>`).join('')}</tbody></table></div>`:''}`;
 $('#season-year').value=seasonYear;$('#season-year').onchange=e=>{seasonYear=e.target.value;loadSalesInsights()};$('#season-product').onchange=e=>{seasonProduct=e.target.value;drawSalesInsights()};$$('[data-explore-season]').forEach(b=>b.onclick=()=>{seasonProduct=b.dataset.exploreSeason;drawSalesInsights();$('#season-peak').scrollIntoView({block:'center'})});
}
let inventoryCategory='visible',inventoryQuery='',inventorySelected=new Set();
const inventoryOut=p=>p.stock<=0||optionsFor(p).some(o=>o.stock<=0);
function inventoryItems(){const collator=new Intl.Collator(lang==='ar'?'ar':'en',{numeric:true,sensitivity:'base'}),query=inventoryQuery.trim().toLocaleLowerCase();return adminData.products.filter(p=>(inventoryCategory==='hidden'?!p.active:inventoryCategory==='out'?p.active&&inventoryOut(p):p.active)&&(!query||(p.name+' '+(p.name_en||'')+' '+(p.source_sku||'')+' '+p.id).toLocaleLowerCase().includes(query))).sort((a,b)=>collator.compare(pname(a),pname(b))||a.id-b.id)}
function inventoryPanel(){
 const all=adminData.products,items=inventoryItems(),ids=new Set(items.map(p=>p.id));inventorySelected=new Set([...inventorySelected].filter(id=>ids.has(id)));
 const hideCount=items.filter(p=>inventorySelected.has(p.id)&&p.active).length,unhideCount=items.filter(p=>inventorySelected.has(p.id)&&!p.active).length;
 return `<div class="inventory-top"><button id="new-product">+ ${t('إضافة منتج','Add product')}</button><label class="inventory-search-label">${t('بحث في المخزون','Search inventory')}<input id="inventory-search" value="${esc(inventoryQuery)}" placeholder="${t('اسم المنتج أو رقمه…','Product name or ID…')}"></label></div><div class="tabs inventory-categories">${[['visible',t('المنتجات الظاهرة','Visible items'),all.filter(p=>p.active).length],['out',t('نفد المخزون','Out of stock'),all.filter(p=>p.active&&inventoryOut(p)).length],['hidden',t('المنتجات المخفية','Hidden items'),all.filter(p=>!p.active).length]].map(([key,label,count])=>`<button type="button" data-inventory-category="${key}" class="${inventoryCategory===key?'active':''}">${label} (${count})</button>`).join('')}</div><p class="inventory-note">${t('مرتبة أبجدياً. تشمل قائمة نفاد المخزون المنتجات والخيارات غير المتوفرة.','Sorted alphabetically. The out-of-stock list includes unavailable products and options.')}</p><div class="inventory-bulk"><span>${inventorySelected.size} ${t('محدد','selected')}</span><button type="button" id="bulk-hide" ${hideCount?'':'disabled'}>${t('إخفاء المحدد','Hide selected')}</button><button type="button" id="bulk-unhide" ${unhideCount?'':'disabled'}>${t('إظهار المحدد','Unhide selected')}</button><button type="button" id="bulk-delete" ${inventorySelected.size?'':'disabled'}>${t('حذف المحدد','Delete selected')}</button><button type="button" id="clear-inventory-selection" ${inventorySelected.size?'':'disabled'}>${t('إلغاء التحديد','Clear selection')}</button></div><div class="table-wrap"><table id="inventory-table"><thead><tr><th><label><input type="checkbox" id="inventory-select-all" aria-label="${t('تحديد كل النتائج','Select all results')}"> ${t('تحديد الكل','Select all')}</label></th>${[t('المنتج','Product'),t('سعر البيع','Price'),t('التكلفة','Unit cost'),t('المخزون','Stock'),''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${items.map(p=>`<tr data-inventory-row="${p.id}" class="${p.stock<=0?'inventory-row-out':''}"><td><input type="checkbox" data-inventory-select="${p.id}" aria-label="${t('تحديد','Select')} ${esc(pname(p))}" ${inventorySelected.has(p.id)?'checked':''}></td><td><div class="inventory-product">${p.image_url?`<img class="inventory-thumb" src="${esc(p.image_url)}" alt="${esc(pname(p))}" loading="lazy">`:`<span class="inventory-thumb inventory-placeholder" aria-hidden="true">${esc(p.emoji||'📚')}</span>`}<div>${esc(pname(p))}<small>#${p.id} · ${esc(ageLabel(p))} · ${esc(p.language)}${p.active?'':' · '+t('مخفي','Hidden')}${optionsFor(p).length?' · '+optionsFor(p).length+' '+t('خيارات','options'):''}</small>${optionsFor(p).some(o=>o.stock<=0)?`<small class="stock-alert">${t('خيارات غير متوفرة: ','Unavailable options: ')}${optionsFor(p).filter(o=>o.stock<=0).map(o=>esc(o.label)).join('، ')}</small>`:''}</div></div></td><td>${price(p.price)}</td><td>${p.cost_known?price(p.cost):t('غير معروفة','Unknown')}</td><td><strong>${p.stock}</strong>${p.stock<=0?`<small class="stock-alert">${t('نفد المخزون','Out of stock')}</small>`:''}</td><td><button data-edit="${p.id}">${t('تعديل','Edit')}</button> <button data-archive="${p.id}">${p.active?t('إخفاء','Hide'):t('إظهار','Unhide')}</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">${t('لا توجد منتجات مطابقة','No matching products.')}</td></tr>`}</tbody></table></div>`;
}
function drawInventory(){if(view!=='inventory')return;$('#admin-content').innerHTML=inventoryPanel();bindInventory()}
function bindInventory(){
 $('#new-product').onclick=()=>productForm();
 $('#inventory-search').oninput=e=>{const value=e.target.value,position=e.target.selectionStart;inventoryQuery=value;drawInventory();$('#inventory-search').focus();$('#inventory-search').setSelectionRange(position,position)};
 $$('[data-inventory-category]').forEach(b=>b.onclick=()=>{inventoryCategory=b.dataset.inventoryCategory;inventorySelected.clear();drawInventory()});
 $$('[data-inventory-select]').forEach(input=>input.onchange=()=>{if(input.checked)inventorySelected.add(+input.dataset.inventorySelect);else inventorySelected.delete(+input.dataset.inventorySelect);drawInventory()});
 const items=inventoryItems(),selectAll=$('#inventory-select-all');selectAll.checked=items.length>0&&items.every(p=>inventorySelected.has(p.id));selectAll.indeterminate=items.some(p=>inventorySelected.has(p.id))&&!selectAll.checked;selectAll.onchange=()=>{if(selectAll.checked)items.forEach(p=>inventorySelected.add(p.id));else inventorySelected.clear();drawInventory()};
 $('#clear-inventory-selection').onclick=()=>{inventorySelected.clear();drawInventory()};
 const bulk=async active=>{const ids=items.filter(p=>inventorySelected.has(p.id)&&Boolean(p.active)!==active).map(p=>p.id);if(!ids.length)return;if(!active&&!confirm(t('إخفاء المنتجات المحددة ونقلها إلى المخفية؟','Hide the selected products and move them to Hidden items?')))return;try{await api('/api/admin/archive-bulk',{ids,active});adminData.products.forEach(p=>{if(ids.includes(p.id))p.active=active?1:0});inventorySelected.clear();drawInventory();await refresh()}catch(error){toast(error.message)}};
 $('#bulk-hide').onclick=()=>bulk(false);$('#bulk-unhide').onclick=()=>bulk(true);$('#bulk-delete').onclick=async()=>{const ids=items.filter(p=>inventorySelected.has(p.id)).map(p=>p.id);if(!ids.length)return;if(!confirm(ids.length+' '+t('منتج محدد. هل تريد حذفها من المخزون والمتجر؟ ستُحفظ سجلات الطلبات والمشتريات السابقة. استخدم الإخفاء إذا أردت إظهارها لاحقاً.','selected products. Delete them from inventory and the shop? Past order and purchase records will be retained. Use Hide if you want to bring them back later.')))return;try{await api('/api/admin/delete-bulk',{ids});adminData.products=adminData.products.filter(p=>!ids.includes(p.id));inventorySelected.clear();drawInventory();await refresh()}catch(error){toast(error.message)}};
 $$('[data-edit]').forEach(b=>b.onclick=()=>productForm(adminData.products.find(p=>p.id===+b.dataset.edit)));
 $$('[data-archive]').forEach(b=>b.onclick=async()=>{const p=adminData.products.find(p=>p.id===+b.dataset.archive);if(p.active&&!confirm(t('إخفاء المنتج ونقله إلى المخفية؟','Hide this product and move it to Hidden items?')))return;try{await api('/api/admin/archive',{id:p.id,active:!p.active});inventorySelected.delete(p.id);await refresh()}catch(error){toast(error.message)}});
}
function renderAdmin(){const a=adminData;$('#admin h1').textContent=t('إدارة المتجر','Shop management');$('#logout').textContent=t('تسجيل الخروج','Sign out');$('#admin>p').textContent=t('يُحسب الربح الإجمالي من المبيعات المكتملة والتكاليف المعروفة، ويشمل صافي الربح المصاريف والدخل الإضافي المسجلين. تُستبعد الطلبات ذات التكلفة المجهولة من الربح، لذا يبقى الربح غير مكتمل حتى تُعرف تكاليفها. يتم التحقق من التحويلات يدوياً.','Gross profit uses completed sales and known product costs. Net profit also includes the expenses and extra income you record. Unknown-cost orders are excluded from profit, so the profit figure is incomplete until their costs are known. Transfers are verified manually.');const tabs={inventory:t('المخزون','Inventory'),orders:t('طلبات العملاء','Customer orders'),purchases:t('مشتريات الموردين','Supplier purchases'),expenses:t('التكاليف الإضافية','Additional costs'),analysis:t('الأكثر مبيعاً والمواسم','Bestsellers & seasons'),settings:t('إعدادات الدفع','Payment settings')};$$('[data-view]').forEach(b=>{b.textContent=tabs[b.dataset.view];b.classList.toggle('active',view===b.dataset.view)});renderStatistics();$('#current-metrics').textContent=t('الوضع الحالي (كل التواريخ): ','Current snapshot (all dates): ')+t('طلبات مفتوحة: ','Open orders: ')+a.orders.filter(o=>!['completed','cancelled'].includes(o.status)).length+' · '+t('منتجات بمخزون منخفض: ','Low-stock products: ')+a.products.filter(p=>p.active&&p.stock<=5).length;let html='';
if(view==='inventory'){html=inventoryPanel()}
if(view==='orders'){
 const list=a.orders.filter(o=>orderFilter==='all'||(orderFilter==='whatsapp'?o.whatsapp_opened_at:orderFilter==='pending'?!['completed','cancelled'].includes(o.status):o.status===orderFilter));
 html=`<div class="section-top"><label>${t('عرض الطلبات','Show orders')} <select id="order-filter">${[['all',t('كل الطلبات عند الدفع','All checkout orders')],['whatsapp',t('ضغطوا متابعة واتساب','WhatsApp payment clicked')],['pending',t('بانتظار المعالجة','Awaiting processing')],['completed',t('تم الدفع والمعالجة','Paid & processed')],['cancelled',t('ملغية','Cancelled')]].map(([k,v])=>`<option value="${k}" ${orderFilter===k?'selected':''}>${v}</option>`).join('')}</select></label><button id="refresh-orders">${t('تحديث الطلبات','Refresh orders')}</button></div><p class="notice">${t('تُحفظ الطلبات قبل فتح واتساب. الضغط على واتساب لا يثبت إرسال الرسالة أو الدفع. بعد التحقق من التحويل اختر تم الدفع والمعالجة لاحتساب البيع والربح، أو ملغي لإعادة المخزون.','Orders are saved before WhatsApp opens. A click does not prove a message was sent or payment received. After verifying the transfer, select Paid & processed to count the sale and gross profit, or Cancelled to restore stock.')}</p>`;
 html+=list.length?`<div class="table-wrap"><table><thead><tr>${['#',t('العميل والتوصيل','Customer & delivery'),t('المنتجات','Items'),t('المجموع','Subtotal'),t('خطوة واتساب','WhatsApp step'),t('الحالة','Status')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${list.map(o=>`<tr><td>#${o.id}<small>${esc(o.created)}</small></td><td>${esc(o.customer)}<small>${esc(o.phone)}</small><small>${o.delivery_method==='home'?t('توصيل للمنزل','Home delivery'):o.delivery_method==='office'?t('استلام من مكتب التوصيل','Delivery-office pickup'):t('طريقة التوصيل غير محددة','Delivery not specified')}${o.delivery_method?' · Geenakum / جيناكم':''}</small><small>${esc(o.address)}</small></td><td>${o.lines.map(l=>`${esc(l.name)}${l.option_label?' — '+esc(l.option_label):''} × ${l.quantity}`).join('<br>')}</td><td>${price(o.total)}${o.cost_known?'':`<small class="low">${t('تكلفة غير معروفة: الربح غير محسوب','Unknown cost: profit excluded')}</small>`}</td><td>${o.whatsapp_opened_at?t('ضغط متابعة واتساب','Clicked WhatsApp'):t('وصل للدفع','Reached checkout')}<small>${esc(o.whatsapp_opened_at||'')}</small></td><td><select data-status="${o.id}" ${o.status==='cancelled'?'disabled':''}>${Object.entries(statuses()).map(([k,v])=>`<option value="${k}" ${o.status===k?'selected':''}>${v}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">${t('لا توجد طلبات مطابقة','No matching orders.')}</p>`;
}

if(view==='purchases'){html=`<button id="new-purchase">+ ${t('إضافة أمر شراء','Add purchase order')}</button><p class="notice">${t('تتبّع أوامر الشراء ثم سجّل الاستلام لإضافة المخزون وتحديث التكلفة بالمتوسط المرجّح.','Track purchase orders, then receive them to increase stock and update the weighted average unit cost.')}</p><div class="table-wrap"><table><thead><tr>${[t('المورد','Supplier'),t('المنتج','Product'),t('الكمية','Quantity'),t('التكلفة الإجمالية','Total cost'),t('التاريخ','Date'),t('الحالة','Status')].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${a.purchases.map(p=>`<tr><td>${esc(p.supplier)}</td><td>${esc(pname(a.products.find(x=>x.id===p.product_id)||{name:p.product_name||'#'+p.product_id}))}${p.option_label?`<small>${esc(p.option_label)}</small>`:''}</td><td>${p.quantity}</td><td>${price(p.quantity*p.unit_cost)}</td><td>${esc(p.created)}</td><td>${p.status==='ordered'?`<button data-receive="${p.id}">${t('تسجيل الاستلام','Receive stock')}</button>`:t('مستلم','Received')}</td></tr>`).join('')}</tbody></table></div>`}
if(view==='analysis'){html='<section id="sales-insights"></section>'}
if(view==='expenses'){html=`<p>${t('جارٍ تحميل التكاليف…','Loading costs…')}</p>`}
if(view==='settings'){html=`<h2>${t('إعدادات التحويل والدفع','Transfer & payment settings')}</h2><p class="notice">${t('عدّل البيانات هنا واضغط حفظ. يظهر التحويل برقم الهاتف أولاً، ثم الحساب البنكي. تُعرض هذه البيانات للعملاء ولا يتم خصم مبالغ تلقائياً.','Edit the details below and save. Phone transfer appears first, followed by bank transfer. Customers see these details; no automatic charges are made.')}</p><form id="bank-form">${[['whatsapp_number',t('رقم واتساب المتجر مع رمز الدولة (مثال: 96899192820)','Shop WhatsApp number with country code (e.g. 96899192820)')],['transfer_phone',t('رقم هاتف التحويل — الخيار الأول','Transfer phone number — first option')],['bank_name',t('اسم البنك','Bank name')],['bank_holder',t('اسم صاحب الحساب','Account holder')],['bank_account',t('رقم الحساب','Account number')],['bank_iban','IBAN'],['bank_swift',t('رمز SWIFT','SWIFT code')]].map(([k,v])=>`<label>${v}<input name="${k}" value="${esc(settings[k]||'')}" maxlength="200" dir="ltr" ${['transfer_phone','whatsapp_number'].includes(k)?'type="tel"':''}></label>`).join('')}<button type="submit">${t('حفظ بيانات الدفع','Save payment details')}</button></form><h3>${t('معاينة ما يظهر للعميل','Customer payment preview')}</h3>${bankInfo()}<p>${t('الدفع بالبطاقة يتطلب تكامل مزود دفع وحساب تاجر.','Card payments require a payment provider integration and a merchant account.')}</p>`}

$('#admin-content').innerHTML=html;if(view==='inventory')bindInventory();if($('#order-filter'))$('#order-filter').onchange=e=>{orderFilter=e.target.value;renderAdmin()};if($('#refresh-orders'))$('#refresh-orders').onclick=()=>refresh().catch(e=>toast(e.message));$$('[data-archive]').forEach(b=>b.onclick=async()=>{const p=a.products.find(p=>p.id===+b.dataset.archive);if(p.active&&!confirm(t('إخفاء المنتج عن العملاء؟ سيبقى في قائمة المخزون مع بياناته وطلباته.','Hide this product from customers? It stays in inventory with its details and order history.')))return;try{await api('/api/admin/archive',{id:p.id,active:!p.active});await refresh()}catch(e){toast(e.message)}});if($('#new-product'))$('#new-product').onclick=()=>productForm();$$('[data-edit]').forEach(b=>b.onclick=()=>productForm(a.products.find(p=>p.id===+b.dataset.edit)));if($('#new-purchase'))$('#new-purchase').onclick=purchaseForm;$$('[data-receive]').forEach(b=>b.onclick=async()=>{try{await receivePurchase(+b.dataset.receive)}catch(e){toast(e.message)}});$$('[data-status]').forEach(s=>s.onchange=async()=>{if(['paid','completed'].includes(s.value)&&!confirm(t('هل تحققت من استلام التحويل في حسابك البنكي؟','Have you verified receipt in your bank account?'))){renderAdmin();return}try{await api('/api/admin/status',{id:+s.dataset.status,status:s.value,payment_verified:s.value==='completed'});await refresh()}catch(e){toast(e.message);renderAdmin()}});if($('#bank-form'))$('#bank-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/settings',Object.fromEntries(new FormData(e.target)));settings=await api('/api/settings');renderAdmin();toast(t('تم الحفظ','Saved'))}catch(err){toast(err.message)}}}
const costLabels=()=>({shipping:t('التوصيل','Shipping'),transfer:t('رسوم التحويل','Transfer fees'),packaging:t('التغليف','Packaging'),other:t('أخرى','Other')});
function drawExpenses(range){
 const rows=(adminData.adjustments||[]).filter(e=>!e.voided&&(!range.start_date||(e.incurred_on>=range.start_date&&e.incurred_on<=range.end_date)));
 $('#admin-content').innerHTML=`<button id="new-expense">+ ${t('إضافة تكلفة أو دخل توصيل','Add cost or delivery income')}</button><p class="notice">${t('أدخل التكلفة الفعلية: التوصيل، رسوم التحويل، التغليف أو غيرها. سجّل المبالغ التي يدفعها العميل للتوصيل كدخل إضافي. لا تسجّل تكلفة شراء المنتجات هنا مرة أخرى، فهي ضمن تكلفة المنتجات المباعة.','Record actual shipping costs, transfer fees, packaging or other expenses. Record delivery money collected from the customer as extra income. Do not enter product purchase costs again here; those are included in the cost of sold products.')}</p><p>${t('السجلات ضمن الفترة المحددة أعلاه. ربط السجل بطلب اختياري.','Entries follow the statistics period above. Linking an entry to an order is optional.')}</p>${rows.length?`<div class="table-wrap"><table><thead><tr>${[t('التاريخ','Date'),t('النوع','Type'),t('الفئة','Category'),t('المبلغ','Amount'),t('الطلب / الملاحظات','Order / notes'),''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.incurred_on)}</td><td>${e.kind==='expense'?t('تكلفة','Cost'):t('دخل إضافي','Extra income')}</td><td>${costLabels()[e.category]}</td><td>${price(e.amount)}</td><td>${e.order_id?'#'+e.order_id:''}<small>${esc(e.note)}</small></td><td><button data-edit-expense="${e.id}">${t('تعديل','Edit')}</button> <button data-void-expense="${e.id}">${t('إزالة','Remove')}</button></td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">${t('لا توجد سجلات في هذه الفترة','No entries for this period.')}</p>`}`;
 $('#new-expense').onclick=()=>expenseForm();
 $$('[data-edit-expense]').forEach(b=>b.onclick=()=>expenseForm(adminData.adjustments.find(e=>e.id===+b.dataset.editExpense)));
 $$('[data-void-expense]').forEach(b=>b.onclick=async()=>{if(!confirm(t('إزالة هذا السجل من حساب الربح؟','Remove this entry from the profit calculation?')))return;try{await api('/api/admin/void-adjustment',{id:+b.dataset.voidExpense});await refresh()}catch(e){toast(e.message)}});
}
function expenseForm(entry={}){
 modal(`<h2>${t('تكلفة أو دخل إضافي','Cost or extra income')}</h2><form id="expense-form"><label>${t('نوع السجل','Entry type')}<select name="kind"><option value="expense">${t('تكلفة مدفوعة','Expense paid')}</option><option value="income">${t('دخل إضافي / مبلغ توصيل محصل','Extra income / delivery collected')}</option></select></label><label>${t('الفئة','Category')}<select name="category"></select></label>${field('amount',t('المبلغ (ر.ع.)','Amount (OMR)'),entry.amount?entry.amount/1000:'','number')}${field('incurred_on',t('تاريخ التكلفة أو الدخل','Cost or income date'),entry.incurred_on||omanToday(),'date')}<label>${t('ربط بطلب (اختياري)','Link to order (optional)')}<select name="order_id"><option value="">${t('بدون طلب / تكلفة عامة','No order / general business cost')}</option>${adminData.orders.map(o=>`<option value="${o.id}">#${o.id} · ${esc(o.customer)}</option>`).join('')}</select></label><label>${t('ملاحظات (اختياري)','Notes (optional)')}<textarea name="note" maxlength="1000">${esc(entry.note||'')}</textarea></label><button type="submit">${t('حفظ السجل','Save entry')}</button></form>`);
 const form=$('#expense-form');form.elements.kind.value=entry.kind||'expense';form.elements.order_id.value=entry.order_id||'';
 const categories=()=>{const keys=form.elements.kind.value==='expense'?['shipping','transfer','packaging','other']:['shipping','other'];form.elements.category.innerHTML=keys.map(key=>`<option value="${key}">${costLabels()[key]}</option>`).join('')};
 categories();if(entry.category)form.elements.category.value=entry.category;form.elements.kind.onchange=categories;
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{await api('/api/admin/adjustment',{...Object.fromEntries(new FormData(form)),id:entry.id});$('#modal').close();await refresh()}catch(error){toast(error.message);button.disabled=false}};
}
function field(name,label,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?`min="${name==='quantity'?1:0}" step="${['stock','quantity'].includes(name)?1:'0.001'}"`:''} ${required?'required':''}></label>`}
function setupProductPhotos(form,p){
 let photos=[...productPhotos(p)],busy=false;
 const renderPhotos=()=>{$('#product-photo-previews').innerHTML=photos.map((url,index)=>`<div class="photo-edit-card"><img src="${esc(url)}" alt="${t('صورة المنتج','Product photo')} ${index+1}"><button type="button" data-main-photo="${index}" ${index===0?'disabled':''}>${index===0?t('الصورة الرئيسية','Main photo'):t('اجعلها الرئيسية','Make main')}</button><button type="button" data-remove-photo="${index}">${t('إزالة','Remove')}</button></div>`).join('')||`<p>${t('لم تُضف صور بعد','No photos added yet.')}</p>`;$$('[data-main-photo]').forEach(b=>b.onclick=()=>{const [image]=photos.splice(+b.dataset.mainPhoto,1);photos.unshift(image);renderPhotos()});$$('[data-remove-photo]').forEach(b=>b.onclick=()=>{photos.splice(+b.dataset.removePhoto,1);renderPhotos()})};
 const addLink=()=>{const input=form.elements.image_url,url=input.value.trim();if(!url)return;if(!url.startsWith('https://')&&!/^\/(uploads|catalog-images)\/[a-f0-9]+\.(jpg|png|webp)$/.test(url))throw Error(t('أدخل رابط HTTPS صالحاً','Enter a valid HTTPS image link'));if(!photos.includes(url)){if(photos.length>=30)throw Error(t('الحد الأقصى ٣٠ صورة','Maximum 30 photos'));photos.push(url)}input.value='';renderPhotos()};
 $('#add-photo-link').onclick=()=>{try{addLink()}catch(e){toast(e.message)}};
 $('#upload-product-photos').onclick=()=>$('#product-photo-files').click();
 $('#product-photo-files').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;if(photos.length+files.length>30||files.length>10||files.some(f=>f.size>8*1024*1024)||files.reduce((n,f)=>n+f.size,0)>20*1024*1024){toast(t('تأكد من عدد الصور وحجمها ضمن الحدود المعروضة','Check the photo count and size limits shown above'));e.target.value='';return}
 busy=true;activePhotoUpload=true;form.querySelector('button[type=submit]').disabled=true;$('#upload-product-photos').disabled=true;$('#photo-upload-status').textContent=t('جارٍ رفع الصور…','Uploading photos…');
 try{const data=new FormData();files.forEach(file=>data.append('photos',file));const response=await fetch('/api/admin/upload',{method:'POST',body:data});const result=await response.json();if(!response.ok)throw Error(result.error||'Upload failed');photos=[...new Set([...photos,...result.images])];renderPhotos();$('#photo-upload-status').textContent=t('تم رفع الصور. احفظ المنتج لتطبيق التغييرات.','Photos uploaded. Save the product to apply your changes.')}
 catch(error){$('#photo-upload-status').textContent=error.message}
 finally{busy=false;activePhotoUpload=false;form.querySelector('button[type=submit]').disabled=false;$('#upload-product-photos').disabled=false;e.target.value=''}
 };
 renderPhotos();return {getImages(){if(busy)throw Error(t('انتظر اكتمال رفع الصور','Wait for the photos to finish uploading'));addLink();return photos}};
}
function setupProductOptions(form,p){
 let options=optionsFor(p).map(o=>({...o,price:o.price===null?'':o.price/1000})),archived=[...(p.archived_options||[])];
 const capture=()=>{options=$$('[data-option-row]').map(row=>({id:row.dataset.id||undefined,label:row.querySelector('[data-option-label]').value,stock:row.querySelector('[data-option-stock]').value,price:row.querySelector('[data-option-price]').value}))};
 const stockTotal=()=>{form.elements.stock.readOnly=options.length>0;if(options.length)form.elements.stock.value=options.reduce((sum,o)=>sum+(Number(o.stock)||0),0);else if(optionsFor(p).length)form.elements.stock.value=0};
 const renderOptions=()=>{$('#option-editor').innerHTML=options.map((o,i)=>`<div class="option-edit-row" data-option-row="${i}" data-id="${esc(o.id||'')}"><label>${t('اسم الخيار','Option name')}<input data-option-label value="${esc(o.label)}" maxlength="150" placeholder="${t('مثال: أولاد / أزرق','e.g. Boys / Blue')}" required></label><label>${t('المخزون','Stock')}<input data-option-stock type="number" min="0" step="1" value="${o.stock}" required></label><label>${t('سعر خاص (اختياري)','Price override (optional)')}<input data-option-price type="number" min="0" step="0.001" value="${esc(o.price)}" placeholder="${t('سعر المنتج','Product price')}"></label><button type="button" data-remove-option="${i}">${t('إزالة الخيار','Remove option')}</button></div>`).join('');$$('[data-option-row] input').forEach(input=>input.oninput=()=>{capture();stockTotal()});$$('[data-remove-option]').forEach(b=>b.onclick=()=>{capture();const [removed]=options.splice(+b.dataset.removeOption,1);if(removed.id)archived.push({...removed,price:removed.price===''?null:Number(removed.price)*1000});renderOptions()});$('#archived-option-editor').innerHTML=archived.length?`<details><summary>${t('خيارات سابقة / مخزون مخفي','Previous options / hidden stock')} (${archived.length})</summary>${archived.map((o,i)=>`<p>${esc(o.label)} · ${o.stock} <button type="button" data-restore-option="${i}">${t('استعادة الخيار','Restore option')}</button></p>`).join('')}</details>`:'';$$('[data-restore-option]').forEach(b=>b.onclick=()=>{capture();const [o]=archived.splice(+b.dataset.restoreOption,1);options.push({...o,price:o.price===null?'':o.price/1000});renderOptions()});stockTotal()};
 $('#add-product-option').onclick=()=>{capture();options.push({label:'',stock:0,price:''});renderOptions();$$('[data-option-label]').at(-1).focus()};
 renderOptions();return {getOptions(){capture();return options}};
}
function productForm(p={}){modal(`<h2>${t('بيانات المنتج','Product details')}</h2><form id="product-form"><div class="form-grid">${field('name',t('الاسم العربي','Arabic name'),p.name)}${field('name_en',t('الاسم الإنجليزي','English name'),p.name_en|| (p.id?seedNames[p.id-1]||'':''),'text',false)}${field('price',t('السعر (ر.ع.)','Price (OMR)'),(p.price||0)/1000,'number')}<label>${t('التكلفة (ر.ع.) — اتركها فارغة إن لم تُعرف','Cost (OMR) — leave blank if unknown')}<input name="cost" type="number" min="0" step="0.001" value="${p.cost_known?(p.cost||0)/1000:''}"></label>${field('stock',t('المخزون','Stock'),p.stock||0,'number')}${field('emoji',t('رمز الغلاف','Cover symbol'),p.emoji||'📚')}<label>${t('الفئة','Category')}<select name="category"><option value="books">${t('كتب','Books')}</option><option value="toys">${t('ألعاب','Toys')}</option></select></label><fieldset class="age-picker"><legend>${t('الفئات العمرية','Age ranges')}</legend><p>${t('اختر كل الفئات المناسبة للمنتج. يمكنك اختيار أكثر من فئة، أو تركها فارغة إذا لم تُحدد بعد.','Select every suitable age range. You can select more than one, or leave all unchecked if not specified yet.')}</p><div>${ageRanges.map(age=>`<label><input type="checkbox" name="ages" value="${age}" ${productAges(p).includes(age)?'checked':''}><span><bdi>${age}</bdi> ${t('سنوات','years')}</span></label>`).join('')}</div></fieldset><label>${t('لغة المنتج','Product language')}<select name="language"><option value="العربية">${t('العربية','Arabic')}</option><option value="English">${t('الإنجليزية','English')}</option></select></label></div><fieldset class="option-picker"><legend>${t('خيارات المنتج','Product options')}</legend><p class="photo-help">${t('أضف اختيارات مثل أولاد، بنات أو ألوان. لكل خيار مخزونه الخاص. اترك السعر فارغاً لاستخدام سعر المنتج. عند وجود خيارات يُحسب المخزون من مجموعها.','Add choices such as Boys, Girls or colors. Each choice has its own stock. Leave price blank to use the product price. Product stock is calculated from its options.')}<br>${t('تكلفة المنتج الأساسية تُستخدم لكل الخيارات.','The product unit cost applies to all options.')}</p><div id="option-editor"></div><button type="button" id="add-product-option">+ ${t('إضافة خيار','Add option')}</button><div id="archived-option-editor"></div></fieldset><fieldset class="photo-picker"><legend>${t('صور المنتج','Product photos')}</legend><button type="button" id="upload-product-photos">${t('رفع صور من الجهاز','Upload photos from device')}</button><input id="product-photo-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><p class="photo-help">${t('حتى ٣٠ صورة للمنتج، و١٠ صور لكل دفعة. JPG أو PNG أو WebP، حتى ٨ ميغابايت للصورة و٢٠ ميغابايت للدفعة. اختر الصورة الرئيسية من المعاينات.','Up to 30 photos per product, 10 per upload. JPG, PNG or WebP; up to 8 MB per photo and 20 MB per batch. Choose the main photo from the previews.')}</p><div id="photo-upload-status" role="status"></div><div id="product-photo-previews"></div><label>${t('أو أضف رابط صورة (اختياري)','Or add an image link (optional)')}<input name="image_url" type="text" placeholder="https://…"></label><button type="button" id="add-photo-link">${t('إضافة الرابط','Add link')}</button></fieldset><label>${t('الوصف العربي','Arabic description')}<textarea name="description" required maxlength="10000">${esc(p.description||'')}</textarea></label><label>${t('الوصف الإنجليزي','English description')}<textarea name="description_en" maxlength="10000">${esc(p.description_en||'')}</textarea></label><button type="submit">${t('حفظ المنتج','Save product')}</button></form>`);for(const k of ['category'])if(p[k])$('#product-form').elements[k].value=p[k];$('#product-form').elements.language.value=p.language==='English'?'English':'العربية';const photoEditor=setupProductPhotos($('#product-form'),p);const optionEditor=setupProductOptions($('#product-form'),p);$('#product-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/product',{...Object.fromEntries(new FormData(e.target)),ages:new FormData(e.target).getAll('ages'),images:photoEditor.getImages(),options:optionEditor.getOptions(),id:p.id});$('#modal').close();await refresh()}catch(err){toast(err.message)}}}
function purchaseForm(){modal(`<h2>${t('أمر شراء مورد','Supplier purchase order')}</h2><form id="purchase-form"><label>${t('المنتج','Product')}<select name="product_id">${adminData.products.map(p=>`<option value="${p.id}">${esc(pname(p))}</option>`).join('')}</select></label><label id="purchase-option-row" hidden>${t('الخيار','Option')}<select name="option_id"></select></label>${field('supplier',t('اسم المورد','Supplier'))}${field('quantity',t('الكمية المستلمة','Quantity received'),1,'number')}${field('unit_cost',t('تكلفة الوحدة (ر.ع.)','Unit cost (OMR)'),0,'number')}<label>${t('الحالة','Status')}<select name="status"><option value="ordered">${t('قيد الانتظار','Ordered — awaiting delivery')}</option><option value="received">${t('تم الاستلام','Already received')}</option></select></label><button type="submit">${t('تسجيل الاستلام','Receive stock')}</button></form>`);const purchaseFormElement=$('#purchase-form');const updatePurchaseOptions=()=>{const product=adminData.products.find(p=>p.id===+purchaseFormElement.elements.product_id.value),options=optionsFor(product);$('#purchase-option-row').hidden=!options.length;purchaseFormElement.elements.option_id.innerHTML='<option value="">'+t('اختر الخيار','Choose option')+'</option>'+options.map(o=>`<option value="${o.id}">${esc(o.label)}</option>`).join('');purchaseFormElement.elements.option_id.required=options.length>0};purchaseFormElement.elements.product_id.onchange=updatePurchaseOptions;updatePurchaseOptions();$('#purchase-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/purchase',Object.fromEntries(new FormData(e.target)));$('#modal').close();await refresh()}catch(err){toast(err.message)}}}
async function receivePurchase(id){const purchase=adminData.purchases.find(p=>p.id===id),product=adminData.products.find(p=>p.id===purchase.product_id)||{options:purchase.product_options||[]},options=optionsFor(product);if(options.length&&!options.some(o=>o.id===purchase.option_id)){modal(`<h2>${t('اختر خيار الاستلام','Choose the option received')}</h2><form id="receive-option-form"><select name="option_id" required>${options.map(o=>`<option value="${o.id}">${esc(o.label)}</option>`).join('')}</select><button type="submit">${t('تسجيل الاستلام','Receive stock')}</button></form>`);$('#receive-option-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/receive',{id,option_id:e.target.elements.option_id.value});$('#modal').close();await refresh()}catch(error){toast(error.message)}};return}await api('/api/admin/receive',{id});await refresh()}
async function loadProducts(){products=await api('/api/products');render()}
async function refresh(){await Promise.all([loadAdmin(),loadProducts()]);renderAdmin()}
translate();Promise.all([loadProducts(),api('/api/settings').then(s=>settings=s)]).catch(e=>toast(e.message));
